    },
    {
      "id": "language-requirements",
      "title": "Local language requirements for jobs",
      "claims": [
        {
          "text": "Approximately 95 % of job listings require local language proficiency.",
          "evidence": [
            26
          ]
        },
        {
          "text": "Language requirements cause many candidates to be filtered out early.",
          "evidence": [
            27
          ]
        },
        {
          "text": "Typical required level is B2; B1 may be accepted; a certificate is usually not required.",
          "evidence": [
            46
          ]
        },
        {
          "text": "There are occasional hires despite lacking the local language.",
          "evidence": [
            29
          ]
        }
      ]
    },
    {
      "id": "job-search-experience",
      "title": "Job search experiences and strategies",
      "claims": [
        {
          "text": "LinkedIn is recommended as a platform for job hunting.",
          "evidence": [
            18
          ]
        },
        {
          "text": "Sending about 100 applications resulted in only three interview invitations.",
          "evidence": [
            21
          ]
        },
        {
          "text": "Candidates with three years of experience still receive few interview callbacks.",
          "evidence": [
            23
          ]
        },
        {
          "text": "A candidate was invited to a mid‑level interview despite zero commercial experience, possibly due to near‑master’s education.",
          "evidence": [
            28
          ]
        },
        {
          "text": "Higher education rarely influences hiring decisions.",
          "evidence": [
            32
          ]
        },
        {
          "text": "Applicants often apply to any job that does not list a local language requirement.",
          "evidence": [
            36
          ]
        },
        {
          "text": "Applicants may accept a minimal salary after stating a desire for higher pay.",
          "evidence": [
            37
          ]
        }
      ]
    },
    {
      "id": "salary-compensation",
      "title": "Salary expectations and compensation",
      "claims": [
        {
          "text": "Salaries in Europe are generally higher than in Ukraine, but this is seldom a decisive factor.",
          "evidence": [
            35
          ]
        },
        {
          "text": "One participant accepted a minimal salary that was still higher than a fast‑food wage.",
          "evidence": [
            37
          ]
        }
      ]
    },
    {
      "id": "language-learning",
      "title": "Language learning and practice",
      "claims": [
        {
          "text": "B2 level proficiency is most commonly requested; B1 may be sufficient; certificates are not typically demanded.",
          "evidence": [
            46
          ]
        },
        {
          "text": "A participant is learning Slovak due to discomfort with language barrier in everyday situations.",
          "evidence": [
            47
          ]
        },
        {
          "text": "Using Discord channels for English conversation practice was suggested.",
          "evidence": [
            56,
            57
          ]
        }
      ]
    },
    {
      "id": "future-move-considerations",
      "title": "Future relocation considerations",
      "claims": [
        {
          "text": "One participant is considering attending a tech event in Warsaw.",
          "evidence": [
            59
          ]
        },
        {
          "text": "Living in Austria is viewed as the best option by a participant, though Ireland, Norway, and Spain were also considered.",
          "evidence": [
            60
          ]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "Use LinkedIn to search for job opportunities.",
      "evidence": [
        18
      ]
    },
    {
      "text": "Apply to any job that does not require local language proficiency.",
      "evidence": [
        36
      ]
    },
    {
      "text": "List B2 language proficiency on the résumé even if actual level is B1, and skip providing a certificate.",
      "evidence": [
        46
      ]
    },
    {
      "text": "Accept the minimal offered salary when seeking employment quickly.",
      "evidence": [
        37
      ]
    },
    {
      "text": "Choose to stay in Austria as the preferred country among considered options.",
      "evidence": [
        60
      ]
    }
  ],
  "openQuestions": [
    {
      "text": "What are the approximate salaries, and did you apply for a junior position?",
      "evidence": [
        34
      ]
    }
  ]
